"""A row generated by ``create()`` has its log filed under that row on the Celery route too.

Intent: the nesting promised by docs/calculations/logging.md must not depend on
where a calculation runs. With ``CELERY_ACTIVE=true``, a root calculation runs in
the generic ``calc_and_save`` task and a ``create()`` whose ``calculate()`` is a
``@lex_shared_task`` fans its rows out through ``CeleryTaskDispatcher``. A worker
gets a copy of the model context stack and writes every line immediately, with
no transaction to defer it. Two things can go wrong there that cannot go wrong
in-process:

- the root arrives with a copy of itself on top of the shipped stack, and must
  not be pushed again as its own child;
- a middle row that dispatches its own children before logging anything is
  unsaved when the stack is copied, so the workers find its node only if it
  exists before the copy is made.

Driven end to end through Celery's eager mode (the same harness as cluster 8h):
real ``.delay()``, real ``@lex_shared_task`` wrapper, real dispatcher; only the
broker is replaced, by Celery itself.

Cluster 15n — scenarios 15.63–15.64. Type: I.
Covers: lex/lex_app/celery_tasks.py (calc_and_save), lex/core/tasks/CeleryTaskDispatcher.py
(copy of the stack per group), lex/core/models/CalculationModel.py
(child_calculation_context, dispatch_calculation_task),
lex/audit_logging/models/CalculationLog.py (prepare_for_dispatch),
lex/audit_logging/utils/ModelContext.py (copy_for_dispatch).
Run: python -m lex pytest lex/test_project/tests/calculation_logging/test_15n_celery_route_log.py -v
"""
from __future__ import annotations

from unittest.mock import patch

import pytest

from lex.audit_logging.models.CalculationLog import CalculationLog
from lex.core.tasks.CeleryTaskDispatcher import CeleryTaskDispatcher
from lex.test_project.tests.celery_async.test_8h_eager_end_to_end import _celery_eager

from . import _CalcLogTestCase
from .models import (
    ALL_MODELS,
    CELERY_ROUTE_MODELS,
    LogCeleryGrandchild,
    LogCeleryLoudChild,
    LogCeleryQuietMiddle,
    LogRootCalc,
)

pytestmark = pytest.mark.calculation_logging


class TestCluster15n_CeleryRouteLog(_CalcLogTestCase):
    """Cluster 15n: the log tree is the same when the work runs in Celery tasks."""

    e2e_models = ALL_MODELS + CELERY_ROUTE_MODELS

    def _save_root_through_celery(self, *, child_mode, units_csv):
        """Save a root with Celery active, watching both dispatch points so a
        scenario can check that its work really ran in Celery tasks."""
        dispatch_root = LogRootCalc.dispatch_calculation_task
        dispatch_groups = CeleryTaskDispatcher.dispatch_calculation_groups
        with _celery_eager(), patch.object(
            LogRootCalc, "dispatch_calculation_task", autospec=True, side_effect=dispatch_root,
        ) as root_dispatch, patch.object(
            CeleryTaskDispatcher, "dispatch_calculation_groups", side_effect=dispatch_groups,
        ) as group_dispatch:
            root = self._save_root(child_mode=child_mode, units_csv=units_csv)
        self.assertTrue(
            root_dispatch.called,
            "Sanity: the root must have been dispatched to a Celery task.",
        )
        self.assertTrue(
            group_dispatch.called,
            "Sanity: the generated rows must have been fanned out through CeleryTaskDispatcher.",
        )
        return root, group_dispatch

    def test_15_63_celery_route_root_is_one_node_and_each_row_has_its_own(self):
        """
        Scenario 15.63: on the Celery route the root is one node and each generated row has its own
        Given: CELERY_ACTIVE with eager tasks; the root's calculate() is
               undecorated, so it runs in the generic calc_and_save task with a
               copy of itself on top of the shipped stack; LogCeleryLoudChild's
               calculate() is a @lex_shared_task, so create() dispatches its rows
        When:  the root is saved with units u1, u2
        Then:  the root has exactly one row, with no parent, rather than a copy
               of itself nested under it; each child has exactly one row, keyed
               by its pk, under the root's row
        """
        root, _ = self._save_root_through_celery(child_mode="celery_loud", units_csv="u1,u2")

        root_row = self.assert_log_row(root, parent=None, contains="root root-celery_loud")
        for unit in ("u1", "u2"):
            child = LogCeleryLoudChild.objects.get(unit=unit)
            self.assert_log_row(child, parent=root_row, contains=f"celery loud {unit}")
        self.assert_total_rows(3)

    def test_15_64_unsaved_middle_dispatching_first_is_one_node(self):
        """
        Scenario 15.64: a middle row that dispatches before logging is one node for every worker
        Given: CELERY_ACTIVE with eager tasks; LogCeleryQuietMiddle's calculate()
               dispatches LogCeleryGrandchild.create() before it logs, while the
               middle row has no primary key, so the grandchildren's task gets
               a copy of the stack holding an unsaved model
        When:  the root is saved with unit u1
        Then:  there is exactly one middle row, keyed by the middle's pk once
               saved, under the root's row and holding "celery middle after u1";
               the grandchild's row hangs off it
        """
        root, group_dispatch = self._save_root_through_celery(
            child_mode="celery_quiet_three_level", units_csv="u1",
        )
        self.assertGreaterEqual(
            group_dispatch.call_count, 2,
            "Sanity: the middle and the grandchild must each have been dispatched.",
        )

        root_row = self.assert_log_row(root, parent=None)
        middle = LogCeleryQuietMiddle.objects.get(unit="u1")
        middle_row = self.assert_log_row(
            middle, parent=root_row, contains="celery middle after u1",
        )
        grandchild = LogCeleryGrandchild.objects.get(unit="u1")
        self.assert_log_row(grandchild, parent=middle_row, contains="celery grandchild u1")
        self.assertEqual(
            CalculationLog.objects.filter(
                calculationId=self.calc_id, content_type__model="logceleryquietmiddle",
            ).count(),
            1,
            "Every worker must file under the same middle node, and the middle "
            "must keep writing to it after its children.",
        )
        self.assert_total_rows(3)
